// seismic_io.tile_read — half-open window reads against the frozen IO
// oracle fixtures (libs/seismic_io/seismic_io_tests/fixtures, generated by
// oracle/generate_io_fixtures.py with segyio cross-checks). Covers:
// metadata descriptors (shape/steps/dt/domain/format/bin-grid probes),
// window dumps for SEG-Y (format 5 + IBM 1) and PWBVOL1 (depth domain),
// bounds/format refusals, and cancellation.

#include <algorithm>
#include <cmath>
#include <optional>
#include <cstdint>
#include <cstdio>
#include <filesystem>
#include <fstream>
#include <limits>
#include <string>
#include <vector>

#include <pwb/domain/json.hpp>
#include <pwb/seismic_io/segy_layout.hpp>
#include <pwb/seismic_io/tile_cache.hpp>
#include <pwb/seismic_io/tile_read.hpp>
#include <pwb/seismic_io/volume_descriptor.hpp>

namespace fs = std::filesystem;

namespace {

int g_failures = 0;

void check(bool ok, const std::string& what) {
    if (!ok) {
        std::fprintf(stderr, "FAIL %s\n", what.c_str());
        ++g_failures;
    }
}

struct BinGridProbe {
    double x = 0.0;
    double y = 0.0;
    double il_frac = 0.0;
    double xl_frac = 0.0;
    double x_roundtrip = 0.0;
    double y_roundtrip = 0.0;
    std::int64_t nearest_il = 0;
    std::int64_t nearest_xl = 0;
};

// Frozen ORACLE-INFERENCE expectation from the manifest: the grid the
// pinned loader's _infer_bin_grid derives from the corner-trace CDPs.
std::optional<pwb::seismic_io::BinGridGeometry> expected_bin_grid(
    const fs::path& fixtures) {
    std::ifstream input(fixtures / "manifest.json");
    std::string text((std::istreambuf_iterator<char>(input)),
                     std::istreambuf_iterator<char>());
    const pwb::domain::Json manifest =
        pwb::domain::Json::parse(text, nullptr, false);
    if (manifest.is_discarded() || !manifest.contains("cases")) {
        return std::nullopt;
    }
    const auto& grid = manifest["cases"]["io_oracle_bins.sgy"]["meta"]
                           ["bin_grid"];
    if (!grid.is_object()) {
        return std::nullopt;
    }
    pwb::seismic_io::BinGridGeometry bin_grid;
    bin_grid.x_origin = grid["x_origin"].get<double>();
    bin_grid.y_origin = grid["y_origin"].get<double>();
    bin_grid.il_azimuth_deg = grid["il_azimuth_deg"].get<double>();
    bin_grid.il_spacing_m = grid["il_spacing_m"].get<double>();
    bin_grid.xl_spacing_m = grid["xl_spacing_m"].get<double>();
    return bin_grid;
}

// Frozen probe expectations from the oracle manifest (computed with the
// pinned loader's inferred BinGridGeometry).
std::vector<BinGridProbe> decode_probes(const fs::path& fixtures) {
    std::ifstream input(fixtures / "manifest.json");
    std::string text((std::istreambuf_iterator<char>(input)),
                     std::istreambuf_iterator<char>());
    const pwb::domain::Json manifest =
        pwb::domain::Json::parse(text, nullptr, false);
    std::vector<BinGridProbe> probes;
    if (manifest.is_discarded() || !manifest.contains("cases")) {
        return probes;
    }
    const auto& case_entry = manifest["cases"]["io_oracle_bins.sgy"];
    for (const auto& raw : case_entry["meta"]["probes"]) {
        BinGridProbe probe;
        probe.x = raw["x"].get<double>();
        probe.y = raw["y"].get<double>();
        probe.il_frac = raw["il_frac"].get<double>();
        probe.xl_frac = raw["xl_frac"].get<double>();
        probe.x_roundtrip = raw["x_roundtrip"].get<double>();
        probe.y_roundtrip = raw["y_roundtrip"].get<double>();
        probe.nearest_il = raw["nearest_il"].get<std::int64_t>();
        probe.nearest_xl = raw["nearest_xl"].get<std::int64_t>();
        probes.push_back(probe);
    }
    return probes;
}

std::vector<float> read_f32(const fs::path& path) {
    std::ifstream input(path, std::ios::binary);
    input.seekg(0, std::ios::end);
    const std::streamsize size = input.tellg();
    input.seekg(0, std::ios::beg);
    std::vector<float> data(static_cast<std::size_t>(size / 4));
    if (!data.empty()) {
        input.read(reinterpret_cast<char*>(data.data()), size);
    }
    return data;
}

struct WindowExpect {
    const char* name;
    std::array<std::int64_t, 3> origin;
    std::array<std::int64_t, 3> extent;
};

// Craft a PWBVOL1 file with an arbitrary header (hostile shapes included)
// and a chosen payload size — the bytes inspect_pwbvol must survive.
void write_pwbvol(const fs::path& path, const std::string& header_json,
                  std::size_t payload_bytes) {
    std::ofstream out(path, std::ios::binary | std::ios::trunc);
    const char magic[8] = {'P', 'W', 'B', 'V', 'O', 'L', '1', '\0'};
    out.write(magic, 8);
    const std::uint32_t header_size =
        static_cast<std::uint32_t>(header_json.size());
    const unsigned char size_le[4] = {
        static_cast<unsigned char>(header_size & 0xff),
        static_cast<unsigned char>((header_size >> 8) & 0xff),
        static_cast<unsigned char>((header_size >> 16) & 0xff),
        static_cast<unsigned char>((header_size >> 24) & 0xff)};
    out.write(reinterpret_cast<const char*>(size_le), 4);
    out.write(header_json.data(), header_size);
    std::vector<char> payload(payload_bytes, '\0');
    out.write(payload.data(), static_cast<std::streamsize>(payload_bytes));
}

std::string pwbvol_header(const std::string& shape) {
    return std::string("{\"version\":1,\"shape\":") + shape
        + ",\"axes\":[\"inline\",\"crossline\",\"sample\"],"
          "\"layout\":\"c-order-f32\",\"axis_starts\":[1,1,0],"
          "\"axis_steps\":[1,1,2],\"axis_units\":[\"1\",\"1\",\"ms\"]}";
}

// Window table mirrors the generator's expected_windows().
std::vector<WindowExpect> windows_for(const std::array<std::int64_t, 3>& shape) {
    return {
        {"full", {0, 0, 0}, shape},
        {"corner", {0, 0, 0}, {2, 2, 3}},
        {"end", {shape[0] - 1, shape[1] - 2, shape[2] - 4}, {1, 2, 4}},
        {"middle", {1, 1, 2}, {2, 2, 3}},
        {"single_trace", {2, 1, 0}, {1, 1, shape[2]}},
    };
}

void compare_window(const std::vector<float>& actual,
                    const std::vector<float>& expected, double max_abs_tol,
                    double max_rel_tol, const std::string& what) {
    check(actual.size() == expected.size(),
          what + ": size " + std::to_string(actual.size()) + " vs "
              + std::to_string(expected.size()));
    std::size_t mask_mismatch = 0;
    double worst = 0.0;
    for (std::size_t i = 0; i < expected.size() && i < actual.size(); ++i) {
        const float e = expected[i];
        const float a = actual[i];
        const bool e_nan = std::isnan(e);
        const bool a_nan = std::isnan(a);
        if (e_nan || a_nan || std::isinf(e) || std::isinf(a)) {
            const bool match = e_nan == a_nan && std::isinf(e) == std::isinf(a)
                               && (!std::isinf(e) || (e > 0) == (a > 0));
            if (!match) {
                ++mask_mismatch;
            }
            continue;
        }
        const double diff =
            static_cast<double>(std::fabs(a - e));
        // Dual criterion |a-e| <= max(max_abs, max_rel*|e|).
        const double allowed =
            std::max(max_abs_tol, max_rel_tol * static_cast<double>(std::fabs(e)));
        worst = std::max(worst, diff - allowed);
    }
    check(mask_mismatch == 0, what + ": non-finite mask mismatch "
              + std::to_string(mask_mismatch));
    check(worst <= 0.0, what + ": tolerance exceeded by "
              + std::to_string(worst));
}

}  // namespace

int main() {
    const fs::path fixtures = [] {
#ifdef PWB_SEISMIC_IO_FIXTURE_ROOT
        return fs::path(PWB_SEISMIC_IO_FIXTURE_ROOT);
#else
        const char* env = std::getenv("PWB_SEISMIC_IO_FIXTURE_ROOT");
        if (env != nullptr && env[0] != '\0') {
            return fs::path(env);
        }
        return fs::path("libs/seismic_io/seismic_io_tests/fixtures");
#endif
    }();
    // ---- Case A: format 5, unsorted grid, NaN/Inf, dt 2 ms ----------------
    {
        std::string error;
        const auto layout =
            pwb::seismic_io::inspect_segy(fixtures / "io_oracle.sgy", &error);
        check(layout.has_value(), "inspect io_oracle.sgy: " + error);
        if (layout.has_value()) {
            const auto& d = layout->descriptor;
            check(d.ni == 6 && d.nc == 4 && d.ns == 10, "case A shape");
            check(d.iline_start == 1.0 && d.iline_step == 1.0,
                  "case A inline axis (grid min; file order is unsorted)");
            check(d.xline_start == 1.0 && d.xline_step == 1.0,
                  "case A crossline axis");
            check(std::fabs(d.sample_step - 2.0) < 1e-12 && d.sample_start == 0.0,
                  "case A sample axis");
            check(d.sample_domain == pwb::seismic_io::SampleDomain::time,
                  "case A domain");
            check(d.format == pwb::seismic_io::SampleFormat::ieee_f32_be,
                  "case A format");
            check(!d.bin_grid.has_value(),
                  "case A has no bin grid (no coordinates)");

            for (const WindowExpect& w : windows_for({6, 4, 10})) {
                pwb::seismic_io::WindowSpec spec;
                spec.origin = w.origin;
                spec.extent = w.extent;
                std::vector<float> out(
                    static_cast<std::size_t>(spec.elements()), 0.0f);
                pwb::seismic_io::CancelFlag cancel;
                const std::size_t got = pwb::seismic_io::read_segy_window(
                    *layout, spec, out, cancel, &error);
                check(got == out.size(),
                      std::string("case A window ") + w.name + ": read");
                compare_window(out,
                               read_f32(fixtures / (std::string("io_oracle.sgy.")
                                                    + w.name + ".f32")),
                               0.0, 0.0,
                               std::string("case A window ") + w.name);
            }
        }
    }

    // ---- Case B: IBM format 1, steps (2, 3), dt 4 ms ----------------------
    {
        std::string error;
        const auto layout = pwb::seismic_io::inspect_segy(
            fixtures / "io_oracle_ibm.sgy", &error);
        check(layout.has_value(), "inspect io_oracle_ibm.sgy: " + error);
        if (layout.has_value()) {
            const auto& d = layout->descriptor;
            check(d.ni == 4 && d.nc == 3 && d.ns == 8, "case B shape");
            check(d.iline_start == 1.0 && d.iline_step == 2.0,
                  "case B inline axis");
            check(d.xline_start == 10.0 && d.xline_step == 3.0,
                  "case B crossline axis");
            check(std::fabs(d.sample_step - 4.0) < 1e-12, "case B dt");
            check(d.format == pwb::seismic_io::SampleFormat::ibm_f32_be,
                  "case B format");
            for (const WindowExpect& w : windows_for({4, 3, 8})) {
                pwb::seismic_io::WindowSpec spec;
                spec.origin = w.origin;
                spec.extent = w.extent;
                std::vector<float> out(
                    static_cast<std::size_t>(spec.elements()), 0.0f);
                pwb::seismic_io::CancelFlag cancel;
                check(pwb::seismic_io::read_segy_window(*layout, spec, out,
                                                        cancel, &error)
                          == out.size(),
                      std::string("case B window ") + w.name + ": read");
                // IBM decode is exactly rounded in both implementations.
                compare_window(
                    out,
                    read_f32(fixtures / (std::string("io_oracle_ibm.sgy.")
                                         + w.name + ".f32")),
                    1e-4, 1e-6, std::string("case B window ") + w.name);
            }
        }
    }

    // ---- Case C: bin-grid calibrated survey -------------------------------
    {
        std::string error;
        const auto layout = pwb::seismic_io::inspect_segy(
            fixtures / "io_oracle_bins.sgy", &error);
        check(layout.has_value(), "inspect io_oracle_bins.sgy: " + error);
        if (layout.has_value()) {
            const auto& d = layout->descriptor;
            check(d.bin_grid.has_value(), "case C bin grid inferred");
            // Expectation = the FROZEN ORACLE INFERENCE (manifest
            // meta.bin_grid): what the pinned loader's _infer_bin_grid
            // yields for these bytes. Its azimuth convention mirrors the
            // construction azimuth (atan2(dx, dy)) — that legacy quirk is
            // the frozen behavior.
            const auto expected_grid = expected_bin_grid(fixtures);
            if (expected_grid.has_value() && d.bin_grid.has_value()) {
                check(std::fabs(d.bin_grid->x_origin
                                - expected_grid->x_origin)
                          < 1.0
                          && std::fabs(d.bin_grid->y_origin
                                       - expected_grid->y_origin)
                                 < 1.0,
                      "case C bin grid origin");
                check(std::fabs(d.bin_grid->il_azimuth_deg
                                - expected_grid->il_azimuth_deg)
                          < 0.05,
                      "case C azimuth");
                check(std::fabs(d.bin_grid->il_spacing_m
                                - expected_grid->il_spacing_m)
                          < 0.5
                          && std::fabs(d.bin_grid->xl_spacing_m
                                       - expected_grid->xl_spacing_m)
                                 < 0.5,
                      "case C spacings");
                // Probe round trips (frozen from the pinned BinGridGeometry).
                const auto probes = decode_probes(fixtures);
                for (const auto& probe : probes) {
                    const auto [il_f, xl_f] =
                        d.bin_grid->xy_to_il_xl(probe.x, probe.y);
                    check(std::fabs(il_f - probe.il_frac) < 1e-3
                              && std::fabs(xl_f - probe.xl_frac) < 1e-3,
                          "case C probe xy->ilxl");
                    const auto [x2, y2] =
                        d.bin_grid->il_xl_to_xy(il_f, xl_f);
                    check(std::fabs(x2 - probe.x_roundtrip) < 5e-2
                              && std::fabs(y2 - probe.y_roundtrip) < 5e-2,
                          "case C probe roundtrip");
                    const auto [nil, nxl] =
                        d.bin_grid->nearest_il_xl(probe.x, probe.y);
                    check(nil == probe.nearest_il && nxl == probe.nearest_xl,
                          "case C probe nearest");
                }
            }
        }
    }

    // ---- Case D: PWBVOL1 with depth axis ----------------------------------
    {
        std::string error;
        const auto layout = pwb::seismic_io::inspect_pwbvol(
            fixtures / "io_oracle.pwbvol", &error);
        check(layout.has_value(), "inspect io_oracle.pwbvol: " + error);
        if (layout.has_value()) {
            const auto& d = layout->descriptor;
            check(d.ni == 3 && d.nc == 5 && d.ns == 7, "case D shape");
            check(d.sample_domain == pwb::seismic_io::SampleDomain::depth,
                  "case D depth domain");
            check(d.sample_unit == "m", "case D unit");
            check(std::fabs(d.sample_step - 2.5) < 1e-12
                      && std::fabs(d.sample_start - 1500.0) < 1e-12,
                  "case D sample axis");
            check(d.byte_order == std::endian::little, "case D endian");
            for (const WindowExpect& w : windows_for({3, 5, 7})) {
                pwb::seismic_io::WindowSpec spec;
                spec.origin = w.origin;
                spec.extent = w.extent;
                std::vector<float> out(
                    static_cast<std::size_t>(spec.elements()), 0.0f);
                pwb::seismic_io::CancelFlag cancel;
                check(pwb::seismic_io::read_pwbvol_window(*layout, spec, out,
                                                          cancel, &error)
                          == out.size(),
                      std::string("case D window ") + w.name + ": read");
                compare_window(
                    out,
                    read_f32(fixtures / (std::string("io_oracle.pwbvol.")
                                         + w.name + ".f32")),
                    0.0, 0.0, std::string("case D window ") + w.name);
            }
        }
    }

    // ---- Refusals ----------------------------------------------------------
    {
        std::string error;
        const auto bad = pwb::seismic_io::inspect_pwbvol(
            fixtures / "io_oracle.sgy", &error);
        check(!bad.has_value()
                  && error.find("bad magic") != std::string::npos,
              "SEG-Y bytes refused as PWBVOL1: " + error);
    }
    {
        std::string error;
        pwb::seismic_io::SegyLayout layout;
        pwb::seismic_io::WindowSpec spec;
        spec.origin = {0, 0, 0};
        spec.extent = {0, 0, 1};
        std::vector<float> out(1);
        check(pwb::seismic_io::read_segy_window(layout, spec, out,
                                                pwb::seismic_io::CancelFlag(),
                                                &error)
                  == 0,
              "empty window refused");
    }
    {
        std::string error;
        const auto layout =
            pwb::seismic_io::inspect_segy(fixtures / "io_oracle.sgy", &error);
        pwb::seismic_io::WindowSpec out_of_bounds;
        out_of_bounds.origin = {0, 0, 0};
        out_of_bounds.extent = {6, 4, 11};  // ns == 10
        std::vector<float> out(6 * 4 * 11);
        check(pwb::seismic_io::read_segy_window(
                  *layout, out_of_bounds, out, pwb::seismic_io::CancelFlag(),
                  &error)
                  == 0
                  && error == "window out of bounds",
              "out-of-bounds window refused");
    }
    {
        // Pre-cancelled flag: the read refuses before touching the file.
        std::string error;
        const auto layout =
            pwb::seismic_io::inspect_segy(fixtures / "io_oracle.sgy", &error);
        pwb::seismic_io::WindowSpec spec;
        spec.origin = {0, 0, 0};
        spec.extent = {1, 1, 4};
        std::vector<float> out(4, 0.0f);
        pwb::seismic_io::CancelFlag cancel;
        cancel.cancel();
        check(pwb::seismic_io::read_segy_window(*layout, spec, out, cancel,
                                                &error)
                  == 0
                  && error == "cancelled",
              "cancelled read refused");
    }

    // ---- #1456: hostile PWBVOL shapes must be refused BEFORE the size
    // comparison — the old code compared the already-wrapped uint64
    // product and let these headers through.
    {
        const fs::path hostile_dir = fs::temp_directory_path()
            / "pwb_seismic_io_hostile";
        fs::create_directories(hostile_dir);

        // Per-axis caps all pass (2^31 each is allowed) but the product
        // 2^31 * 2^31 * 4 == 2^64 wraps to 0 — the old inspector ACCEPTED
        // this header and the window reader then read from wrapped offsets.
        {
            std::string error;
            const fs::path file = hostile_dir / "wrap_shape.pwbvol";
            write_pwbvol(file, pwbvol_header("[2147483648,2147483648,4]"),
                         0);
            const auto bad = pwb::seismic_io::inspect_pwbvol(file, &error);
            check(!bad.has_value()
                      && error.find("payload shape overflows")
                             != std::string::npos,
                  "wrapped shape product refused: " + error);
        }
        // A legal-looking huge product (1e18 elements) does not wrap, but
        // needs 4e18 payload bytes — refused as truncated, not accepted.
        {
            std::string error;
            const fs::path file = hostile_dir / "huge_shape.pwbvol";
            write_pwbvol(file, pwbvol_header("[1000000,1000000,1000000]"),
                         0);
            const auto bad = pwb::seismic_io::inspect_pwbvol(file, &error);
            check(!bad.has_value()
                      && error.find("payload shorter")
                             != std::string::npos,
                  "huge-but-exact product refused by payload size: "
                  + error);
        }
        // Truncated payload for an otherwise valid shape.
        {
            std::string error;
            const fs::path file = hostile_dir / "short_payload.pwbvol";
            write_pwbvol(file, pwbvol_header("[3,5,7]"), 10);
            const auto bad = pwb::seismic_io::inspect_pwbvol(file, &error);
            check(!bad.has_value()
                      && error.find("payload shorter")
                             != std::string::npos,
                  "short payload refused: " + error);
        }
        // Negative axis.
        {
            std::string error;
            const fs::path file = hostile_dir / "negative_axis.pwbvol";
            write_pwbvol(file, pwbvol_header("[-1,5,7]"), 0);
            const auto bad = pwb::seismic_io::inspect_pwbvol(file, &error);
            check(!bad.has_value(), "negative axis refused");
        }

        // Descriptor elements() overflow semantics (public API contract).
        {
            pwb::seismic_io::VolumeDescriptor descriptor;
            check(descriptor.elements().has_value()
                      && *descriptor.elements() == 0,
                  "default descriptor describes zero elements");
            descriptor.ni = descriptor.nc = descriptor.ns = 1000000;
            check(descriptor.elements().has_value()
                      && *descriptor.elements() == 1000000000000000000LL,
                  "legal large product returned exactly");
            descriptor.ni = descriptor.nc = descriptor.ns =
                (1LL << 40);
            check(!descriptor.elements().has_value(),
                  "overflowing product returned nullopt, never wrapped");
            descriptor.ni = -5;
            descriptor.nc = descriptor.ns = 1;
            check(!descriptor.elements().has_value(),
                  "negative axis returned nullopt");
        }

        // Hostile windows against the valid fixture volume: origin+extent
        // must not wrap into a passing bounds check.
        {
            std::string error;
            const auto layout = pwb::seismic_io::inspect_pwbvol(
                fixtures / "io_oracle.pwbvol", &error);
            check(layout.has_value(), "fixture pwbvol still inspects");
            if (layout.has_value()) {
                pwb::seismic_io::WindowSpec spec;
                spec.origin = {0, 0, 0};
                spec.extent = {2, 2,
                               std::numeric_limits<std::int64_t>::max()};
                check(spec.elements() == 0,
                      "overflowing window elements() reports 0");
                std::vector<float> out(4, 0.0f);
                check(pwb::seismic_io::read_pwbvol_window(
                          *layout, spec, out,
                          pwb::seismic_io::CancelFlag(), &error)
                          == 0,
                      "overflowing extent window refused");
                pwb::seismic_io::WindowSpec wrap_origin;
                wrap_origin.origin = {
                    std::numeric_limits<std::int64_t>::max(), 0, 0};
                wrap_origin.extent = {2, 2, 2};
                check(!pwb::seismic_io::window_in_bounds(
                          layout->descriptor, wrap_origin),
                      "origin+extent wrap window out of bounds");
                pwb::seismic_io::WindowSpec int64min_extent;
                int64min_extent.origin = {0, 0, 0};
                int64min_extent.extent = {
                    2, 2, std::numeric_limits<std::int64_t>::min()};
                check(int64min_extent.elements() == 0,
                      "INT64_MIN extent does not UB in elements()");
                check(!pwb::seismic_io::window_in_bounds(
                          layout->descriptor, int64min_extent),
                      "INT64_MIN extent window out of bounds");
            }
        }
    }

    std::printf("%s: %d failure(s)\n", g_failures == 0 ? "PASS" : "FAIL",
                g_failures);
    return g_failures == 0 ? 0 : 1;
}
